enu-presentation=\"mega-side\"]>.wf-nav-children:not(:has(>.wf-nav-item:hover))>.wf-nav-item:first-child>.wf-nav-children{display:block;position:static;left:auto;right:auto;top:auto;bottom:auto;padding:0;margin-left:calc(var(--wf-space-unit)*4);border-left:1px solid var(--wf-color-border);background:transparent;overflow:visible}}"
    }
