  "scripts": [
    {
      "name": "navigation-menu.js",
      "content": "(function(){document.querySelectorAll('[data-wf-header]').forEach(function(header){var toggle=header.querySelector('[data-wf-nav-toggle]');var list=header.querySelector('[data-wf-nav-list]');if(!toggle||!list||toggle.dataset.wfReady==='true'){return;}toggle.dataset.wfReady='true';var close=function(){header.removeAttribute('data-wf-menu-open');toggle.setAttribute('aria-expanded','false');};toggle.addEventListener('click',function(){var open=header.getAttribute('data-wf-menu-open')!=='true';if(open){header.setAttribute('data-wf-menu-open','true');toggle.setAttribute('aria-expanded','true');}else{close();}});list.addEventListener('click',function(event){if(event.target.closest('a')){close();}});document.addEventListener('keydown',function(event){if(event.key==='Escape'){close();}});window.addEventListener('resize',function(){if(window.innerWidth>780){close();}});});})();"
    }
