{
  "formatVersion": 2,
  "contractVersion": 1,
  "componentKey": "live-chat",
  "label": "Live chat",
  "category": "forms",
  "renderMode": "static",
  "targets": [
    "web",
    "mobile"
  ],
  "htmlContent": "<div class="wf-live-chat wf:fixed wf:bottom-5 wf:z-50" data-wf-live-chat data-position="{{setting:position}}" data-title="{{setting:title}}" data-greeting="{{setting:greeting}}" data-offline="{{setting:offline}}" hidden><section class="wf-live-chat__panel" data-wf-chat-panel hidden><header class="wf-live-chat__bar"><strong data-wf-chat-heading></strong><button type="button" data-wf-chat-close>Zatvori</button></header><p class="wf-live-chat__status" data-wf-chat-status></p><p class="wf-live-chat__expected" data-wf-chat-expected></p><div class="wf-live-chat__log" data-wf-chat-log></div><form class="wf-live-chat__form" data-wf-chat-form><div data-wf-chat-identity hidden><input data-wf-chat-name type="text" name="name" maxlength="120" autocomplete="name" placeholder="Ime"><input data-wf-chat-email type="email" name="email" maxlength="200" autocomplete="email" placeholder="Email"></div><textarea data-wf-chat-text name="message" rows="3" maxlength="4000" placeholder="Poruka"></textarea><input data-wf-chat-file type="file" name="file"><button type="submit">Pošalji</button></form></section><button class="wf-live-chat__open" type="button" data-wf-chat-open aria-expanded="false">{{setting:title}}</button></div>",
  "styles": [
    {
      "name": "live-chat.css",
      "content": ".wf-live-chat{position:fixed;z-index:80;right:1.25rem;bottom:1.25rem;font-family:var(--wf-font-body);color:var(--wf-color-text)}
.wf-live-chat[data-position="left"]{right:auto;left:1.25rem}
.wf-live-chat[hidden]{display:none}
.wf-live-chat__open{min-height:48px;border:1px solid var(--wf-color-border);border-radius:999px;background:var(--wf-color-primary);color:#fff;font:inherit;font-weight:var(--wf-heading-weight);padding:.7rem 1.1rem;cursor:pointer;box-shadow:0 10px 24px rgba(15,23,42,.18)}
.wf-live-chat__panel{display:flex;flex-direction:column;width:min(22rem,calc(100vw - 2rem));height:min(34rem,calc(100vh - 7rem));margin-bottom:.6rem;border:1px solid var(--wf-color-border);border-radius:var(--wf-radius);background:var(--wf-color-surface);box-shadow:0 18px 40px rgba(15,23,42,.18);overflow:hidden}
.wf-live-chat__panel[hidden]{display:none}
.wf-live-chat__bar{display:flex;align-items:center;justify-content:space-between;gap:.5rem;padding:.75rem .9rem;background:var(--wf-color-primary);color:#fff}
.wf-live-chat__bar button{border:0;background:transparent;color:inherit;font:inherit;cursor:pointer}
.wf-live-chat__status,.wf-live-chat__expected{margin:0;padding:.55rem .9rem 0;color:var(--wf-color-muted);font-size:.82rem}
.wf-live-chat__log{flex:1;overflow:auto;display:flex;flex-direction:column;gap:.45rem;padding:.8rem .9rem}
.wf-live-chat__msg{max-width:85%;padding:.55rem .7rem;border-radius:var(--wf-radius);background:var(--wf-color-background)}
.wf-live-chat__msg p{margin:0;white-space:pre-wrap}
.wf-live-chat__msg.is-mine{align-self:flex-end;background:color-mix(in srgb,var(--wf-color-primary) 16%,var(--wf-color-surface))}
.wf-live-chat__msg a{display:inline-block;margin-top:.35rem;color:var(--wf-color-primary)}
.wf-live-chat__form{display:grid;gap:.45rem;padding:.75rem .9rem .9rem;border-top:1px solid var(--wf-color-border)}
.wf-live-chat__form input,.wf-live-chat__form textarea{width:100%;border:1px solid var(--wf-color-border);border-radius:var(--wf-radius);background:var(--wf-color-background);color:inherit;font:inherit;padding:.55rem .7rem}
.wf-live-chat__form button{min-height:42px;border:0;border-radius:var(--wf-radius);background:var(--wf-color-primary);color:#fff;font:inherit;font-weight:var(--wf-heading-weight);cursor:pointer}
.wf-live-chat[data-live="true"] .wf-live-chat__open:before{content:"";display:inline-block;width:.55rem;height:.55rem;margin-right:.45rem;border-radius:50%;background:#86efac;vertical-align:middle}
"
    }
  ],
  "scripts": [
    {
      "name": "live-chat.js",
      "content": "(function () {
  var root = document.querySelector('[data-wf-live-chat]');
  if (!root || root.getAttribute('data-wf-ready') === 'true') {
    return;
  }
  root.setAttribute('data-wf-ready', 'true');
  var endpoint = '/incKomponente/webchat.php';
  var storeKey = 'wfLiveChatToken';
  var openBtn = root.querySelector('[data-wf-chat-open]');
  var panel = root.querySelector('[data-wf-chat-panel]');
  var closeBtn = root.querySelector('[data-wf-chat-close]');
  var log = root.querySelector('[data-wf-chat-log]');
  var form = root.querySelector('[data-wf-chat-form]');
  var status = root.querySelector('[data-wf-chat-status]');
  var expected = root.querySelector('[data-wf-chat-expected]');
  var nameInput = root.querySelector('[data-wf-chat-name]');
  var emailInput = root.querySelector('[data-wf-chat-email]');
  var textInput = root.querySelector('[data-wf-chat-text]');
  var fileInput = root.querySelector('[data-wf-chat-file]');
  var identity = root.querySelector('[data-wf-chat-identity]');
  var heading = root.querySelector('[data-wf-chat-heading]');
  var timer = 0;
  var cursor = 0;
  var threadReady = false;
  var state = { enabled: false, uploads: false, askIdentity: false, loggedIn: false };
  if (heading) {
    heading.textContent = root.getAttribute('data-title') || 'Razgovor';
  }

  function token() {
    try {
      return localStorage.getItem(storeKey) || '';
    } catch (error) {
      return '';
    }
  }

  function saveToken(value) {
    try {
      if (value) {
        localStorage.setItem(storeKey, value);
      } else {
        localStorage.removeItem(storeKey);
      }
    } catch (error) {
      return;
    }
  }

  function paintStatus(data) {
    var greeting = root.getAttribute('data-greeting') || '';
    var offline = root.getAttribute('data-offline') || '';
    var text = data && data.message ? data.message : (data && data.live ? greeting : offline);
    if (status) {
      status.textContent = text || '';
    }
    if (expected) {
      expected.textContent = data && data.expected ? data.expected : '';
    }
    root.setAttribute('data-live', data && data.live ? 'true' : 'false');
  }

  function addMessage(message) {
    if (!log || !message || log.querySelector('[data-id="' + message.id + '"]')) {
      return;
    }
    var item = document.createElement('div');
    item.className = 'wf-live-chat__msg' + (message.mine ? ' is-mine' : '');
    item.setAttribute('data-id', String(message.id));
    var body = document.createElement('p');
    body.textContent = message.text || '';
    item.appendChild(body);
    if (message.file && message.file.url) {
      var link = document.createElement('a');
      link.href = message.file.url;
      link.target = '_blank';
      link.rel = 'noopener';
      link.textContent = message.file.name || 'Prilog';
      item.appendChild(link);
    }
    log.appendChild(item);
    log.scrollTop = log.scrollHeight;
  }

  function applyThread(data) {
    if (!data) {
      return;
    }
    if (data.reset) {
      saveToken('');
      cursor = 0;
      if (log) {
        log.textContent = '';
      }
    }
    if (data.token) {
      saveToken(data.token);
    }
    if (typeof data.cursor === 'number') {
      cursor = data.cursor;
    }
    (data.messages || []).forEach(addMessage);
    paintStatus(data);
    if (data.closed && status) {
      status.textContent = 'Razgovor je zatvoren. Nova poruka otvara novi.';
    }
  }

  function applyConfig(data) {
    state = data || state;
    if (!data || data.enabled === false) {
      root.setAttribute('hidden', 'hidden');
      return;
    }
    root.removeAttribute('hidden');
    if (identity) {
      identity.hidden = !!data.loggedIn || !data.askIdentity;
    }
    if (fileInput) {
      fileInput.hidden = !data.uploads;
      if (data.types && data.types.length) {
        fileInput.accept = data.types.map(function (ext) { return '.' + ext; }).join(',');
      }
    }
    paintStatus(data);
    applyThread(data);
  }

  function request(action, extra) {
    var url = endpoint + '?action=' + encodeURIComponent(action) + (extra && extra.query ? extra.query : '');
    var options = { credentials: 'same-origin', headers: { 'Accept': 'application/json' } };
    if (extra && extra.body) {
      options.method = 'POST';
      options.body = extra.body;
      if (!(extra.body instanceof FormData)) {
        options.headers['Content-Type'] = 'application/json';
      }
    }
    return fetch(url, options).then(function (response) {
      return response.json().catch(function () { return { ok: false }; });
    });
  }

  function refresh() {
    var current = token();
    var action = 'poll';
    var query = endpoint + '?action=' + action + '&cursor=' + encodeURIComponent(String(cursor));
    if (current) {
      query += '&token=' + encodeURIComponent(current);
    }
    return fetch(query, { credentials: 'same-origin', headers: { 'Accept': 'application/json' } })
      .then(function (response) { return response.json(); })
      .then(applyThread)
      .catch(function () { return null; });
  }

  function startPoll() {
    stopPoll();
    timer = window.setInterval(refresh, 3000);
  }

  function stopPoll() {
    if (timer) {
      window.clearInterval(timer);
      timer = 0;
    }
  }

  function setOpen(isOpen) {
    if (!panel || !openBtn) {
      return;
    }
    panel.hidden = !isOpen;
    openBtn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    if (isOpen) {
      var ready = threadReady ? Promise.resolve() : request('open', { query: token() ? '&token=' + encodeURIComponent(token()) : '' }).then(function (data) {
        threadReady = true;
        applyThread(data);
      });
      ready.then(function () {
        refresh();
        startPoll();
        if (textInput) {
          textInput.focus();
        }
      });
    } else {
      stopPoll();
    }
  }

  if (openBtn) {
    openBtn.addEventListener('click', function () { setOpen(panel.hidden); });
  }
  if (closeBtn) {
    closeBtn.addEventListener('click', function () { setOpen(false); });
  }
  if (form) {
    form.addEventListener('submit', function (event) {
      event.preventDefault();
      var data = new FormData();
      data.append('action', 'send');
      data.append('token', token());
      data.append('text', textInput ? textInput.value : '');
      data.append('name', nameInput ? nameInput.value : '');
      data.append('email', emailInput ? emailInput.value : '');
      if (fileInput && fileInput.files && fileInput.files[0]) {
        data.append('file', fileInput.files[0]);
      }
      request('send', { body: data }).then(function (payload) {
        if (!payload || payload.ok === false) {
          if (status) {
            status.textContent = payload && payload.error ? payload.error : 'Poruka nije poslata.';
          }
          return;
        }
        if (textInput) {
          textInput.value = '';
        }
        if (fileInput) {
          fileInput.value = '';
        }
        if (log) {
          log.textContent = '';
        }
        cursor = 0;
        applyThread(payload);
      }).catch(function () {
        if (status) {
          status.textContent = 'Poruka nije poslata.';
        }
      });
    });
  }

  request('duty').then(applyConfig).catch(function () {
    root.setAttribute('hidden', 'hidden');
  });
})();
